import { sql } from 'drizzle-orm'
import { boolean, check, index, integer, jsonb, pgTable, primaryKey, text, timestamp, uniqueIndex, uuid } from 'drizzle-orm/pg-core'

// The platform and its tenants (migrations 0094, 0095). An organisation is one institute; every tenant table carries
// org_id, stamped by the database from the transaction's org (app_org()) and enforced by a RESTRICTIVE policy.
// Generated by 0095 and checked by pnpm test:tenancy rather than declared here: each tenant table's `<t>_org_idx`,
// the `<t>_org_id_uq` UNIQUE (org_id, id) on parents, and the `*_orgfk` (org_id, col) companion foreign keys.

/** The id of the org rows belonged to before multi-tenancy (development data and the demo). */
export const SAMPLE_ORG_ID = '00000000-0000-4000-8000-000000000001'
/** The Sample Institute as a host resolves it (tests and seeds sign in to it). */
export const SAMPLE_ORG = { id: SAMPLE_ORG_ID, slug: 'sample', name: 'Sample Institute', status: 'active' }

export const plans = pgTable(
  'plans',
  {
    key: text('key').primaryKey(),
    name: text('name').notNull(),
    description: text('description'),
    priceMonthly: integer('price_monthly').notNull().default(0), // paise, before GST
    priceYearly: integer('price_yearly').notNull().default(0),
    limits: jsonb('limits').$type<PlanLimits>().notNull().default({}),
    modules: text('modules').array().notNull().default(sql`'{}'`),
    isPublic: boolean('is_public').notNull().default(true),
    sort: integer('sort').notNull().default(0),
    isActive: boolean('is_active').notNull().default(true),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  () => [check('plans_key_ck', sql`key ~ '^[a-z][a-z0-9_]{1,39}$'`)],
)
/** null = no limit */
export type PlanLimits = { branches?: number | null; staff?: number | null; activeStudents?: number | null; storageMb?: number | null; messagesPerMonth?: number | null }

export const ORG_STATUSES = ['trial', 'active', 'past_due', 'read_only', 'suspended', 'cancelled'] as const
export type OrgStatus = (typeof ORG_STATUSES)[number]

export const organisations = pgTable(
  'organisations',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    name: text('name').notNull(),
    legalName: text('legal_name'),
    slug: text('slug').notNull(),
    status: text('status').$type<OrgStatus>().notNull().default('trial'),
    planKey: text('plan_key').notNull().default('starter').references(() => plans.key, { onUpdate: 'cascade' }),
    trialEndsAt: timestamp('trial_ends_at', { withTimezone: true }),
    branding: jsonb('branding').$type<Record<string, unknown>>().notNull().default({}),
    numbering: jsonb('numbering').$type<Record<string, string>>().notNull().default({}),
    locale: text('locale').notNull().default('en-IN'),
    timezone: text('timezone').notNull().default('Asia/Kolkata'),
    currency: text('currency').notNull().default('INR'),
    country: text('country').notNull().default('IN'),
    gstin: text('gstin'),
    pan: text('pan'),
    address: text('address'),
    phone: text('phone'),
    email: text('email'),
    ownerUserId: uuid('owner_user_id'), // (id, owner_user_id) -> users (org_id, id): declared in SQL
    features: jsonb('features').$type<Record<string, boolean>>().notNull().default({}),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
  },
  () => [
    uniqueIndex('organisations_slug_uq').on(sql`slug`),
    check('organisations_status_ck', sql`status IN ('trial', 'active', 'past_due', 'read_only', 'suspended', 'cancelled')`),
    check('organisations_slug_ck', sql`slug ~ '^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$'`),
  ],
)

/** The org_id column of a tenant table: stamped from the transaction's org. */
export const orgId = () => uuid('org_id').notNull().default(sql`app_org()`).references(() => organisations.id)

/** Counters that run across a whole org (tickets, help requests, event certificates): minted by app_org_seq() only. */
export const orgSequences = pgTable(
  'org_sequences',
  {
    orgId: orgId(),
    kind: text('kind').notNull(), // TKT | HLP | EVC
    period: text('period').notNull(), // 'ALL', '2026' or FY '2026-27'
    lastValue: integer('last_value').notNull().default(0),
  },
  (t) => [primaryKey({ name: 'org_sequences_pk', columns: [t.orgId, t.kind, t.period] })],
)

export const orgDomains = pgTable(
  'org_domains',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: uuid('org_id').notNull().references(() => organisations.id, { onDelete: 'cascade' }),
    host: text('host').notNull(),
    token: text('token').notNull(), // the DNS TXT record that proves the domain is theirs
    verifiedAt: timestamp('verified_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [uniqueIndex('org_domains_host_uq').on(t.host), index('org_domains_org_idx').on(t.orgId), check('org_domains_host_ck', sql`host = lower(host)`)],
)

/** The platform's own people. They sign in on the platform host only and never see an org's records by default. */
export const platformUsers = pgTable(
  'platform_users',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    name: text('name').notNull(),
    email: text('email').notNull(),
    passwordHash: text('password_hash').notNull(),
    isActive: boolean('is_active').notNull().default(true),
    lastLoginAt: timestamp('last_login_at', { withTimezone: true }),
    createdAt: timestamp('created_at', { withTimezone: true }).notNull().defaultNow(),
  },
  () => [uniqueIndex('platform_users_email_uq').on(sql`lower(email)`)],
)

export const platformConfig = pgTable('platform_config', {
  key: text('key').primaryKey(),
  config: jsonb('config').notNull().default({}),
  secrets: text('secrets'),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().defaultNow(),
})

/** A platform admin working inside an org: a stated reason, read or write, at most an hour; the org sees each one. */
export const supportSessions = pgTable(
  'support_sessions',
  {
    id: uuid('id').primaryKey().defaultRandom(),
    orgId: uuid('org_id').notNull().references(() => organisations.id, { onDelete: 'cascade' }),
    platformUserId: uuid('platform_user_id').notNull().references(() => platformUsers.id),
    byName: text('by_name').notNull().default(''), // the platform admin's name, for the org (it cannot read platform_users)
    reason: text('reason').notNull(),
    mode: text('mode').$type<'read' | 'write'>().notNull().default('read'),
    startedAt: timestamp('started_at', { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    endedAt: timestamp('ended_at', { withTimezone: true }),
    endedBy: text('ended_by'), // platform | org | expired
  },
  (t) => [
    index('support_sessions_org_idx').on(t.orgId, t.startedAt.desc()),
    index('support_sessions_open_idx').on(t.orgId).where(sql`ended_at IS NULL`),
    check('support_sessions_mode_ck', sql`mode IN ('read', 'write')`),
    check('support_sessions_length_ck', sql`expires_at > started_at AND expires_at <= started_at + interval '60 minutes'`),
  ],
)
